const parseNestedParens = (paren_string) => {
  const groups = paren_string.trim().split(/\s+/).filter(Boolean);

  return groups.map((group) => {
    let depth = 0;
    let maxDepth = 0;

    for (const char of group) {
      if (char === '(') {
        depth++;
        if (depth > maxDepth) {
          maxDepth = depth;
        }
      } else if (char === ')') {
        depth--;
      }
    }

    return maxDepth;
  });
};
```

