const separateParenGroups = (paren_string) => {
  const result = [];
  let current = '';
  let depth = 0;

  for (const c of paren_string) {
    if (c === ' ') continue;

    if (c === '(') {
      depth += 1;
      current += c;
    } else if (c === ')') {
      depth -= 1;
      current += c;

      if (depth === 0) {
        result.push(current);
        current = '';
      }
    }
  }

  return result;
};
