const fizzBuzz = (n) => {
  const count7sUpTo = (N, d) => {
    if (N < 0) return 0;
    const digits = String(N).split('').map(Number);
    const len = digits.length;
    const memo = new Map();

    const dp = (pos, rem, tight, started) => {
      if (pos === len) {
        return { count: (started && rem === 0) ? 1 : 0, sum: 0 };
      }
      const key = `${pos},${rem},${tight},${started}`;
      if (memo.has(key)) return memo.get(key);

      const limit = tight ? digits[pos] : 9;
      let totalCount = 0;
      let totalSum = 0;

      for (let digit = 0; digit <= limit; digit++) {
        const newTight = tight && (digit === limit);
        const newStarted = started || (digit !== 0);
        const newRem = (rem * 10 + digit) % d;
        const child = dp(pos + 1, newRem, newTight, newStarted);
        totalCount += child.count;
        totalSum += child.sum;
        if (digit === 7) {
          totalSum += child.count;
        }
      }

      const res = { count: totalCount, sum: totalSum };
      memo.set(key, res);
      return res;
    };

    return dp(0, 0, true, false).sum;
  };

  return count7sUpTo(n - 1, 11) + count7sUpTo(n - 1, 13) - count7sUpTo(n - 1, 143);
};
```

