const findZero = (xs) => {
  const poly = (x) => {
    let result = 0;
    for (let i = xs.length - 1; i >= 0; i--) {
      result = result * x + xs[i];
    }
    return result;
  };

  if (poly(0) === 0) return 0;

  let a = -1;
  let b = 1;
  let fa = poly(a);
  let fb = poly(b);

  while (fa !== 0 && fb !== 0 && (fa < 0) === (fb < 0)) {
    a *= 2;
    b *= 2;
    fa = poly(a);
    fb = poly(b);
  }

  if (fa === 0) return a;
  if (fb === 0) return b;

  for (let i = 0; i < 1000; i++) {
    const m = (a + b) / 2;
    if (m === a || m === b) break;

    const fm = poly(m);
    if (fm === 0) return m;

    if ((fa < 0) !== (fm < 0)) {
      b = m;
      fb = fm;
    } else {
      a = m;
      fa = fm;
    }

    if (Math.abs(b - a) < 1e-15) break;
  }

  return (a + b) / 2;
};
