function modPow(base, exp, mod) {
  let result = 1n;
  base %= mod;
  while (exp > 0n) {
    if ((exp & 1n) === 1n) result = (result * base) % mod;
    base = (base * base) % mod;
    exp >>= 1n;
  }
  return result;
}

function isPrime(n) {
  if (n < 2n) return false;
  if (n === 2n || n === 3n) return true;
  if (n % 2n === 0n) return false;

  let d = n - 1n;
  let s = 0n;
  while (d % 2n === 0n) {
    d /= 2n;
    s += 1n;
  }

  const bases = [
    2n, 3n, 5n, 7n, 11n, 13n, 17n, 19n, 23n, 29n, 31n, 37n,
    41n, 43n, 47n, 53n, 59n, 61n, 67n, 71n, 73n, 79n, 83n, 89n, 97n
  ];

  for (let a of bases) {
    if (a >= n) continue;

    let x = modPow(a, d, n);
    if (x === 1n || x === n - 1n) continue;

    let composite = true;
    let r = 1n;
    while (r < s) {
      x = (x * x) % n;
      if (x === n - 1n) {
        composite = false;
        break;
      }
      r += 1n;
    }

    if (composite) return false;
  }

  return true;
}

const primeFib = (n) => {
  if (n <= 0) return undefined;

  let a = 0n;
  let b = 1n;
  let count = 0;

  while (true) {
    const c = a + b;
    a = b;
    b = c;

    if (isPrime(c)) {
      count++;
      if (count === n) {
        return c <= BigInt(Number.MAX_SAFE_INTEGER) ? Number(c) : c;
      }
    }
  }
};

