const decodeCyclic = (s) => {
  const groups = [];
  for (let i = 0; i < Math.floor((s.length + 2) / 3); i++) {
    groups.push(s.slice(3 * i, Math.min(3 * i + 3, s.length)));
  }

  const decodedGroups = groups.map((group) => {
    if (group.length === 3) {
      return group[2] + group.slice(0, 2);
    }
    return group;
  });

  return decodedGroups.join('');
};
