  let largest = 1;
  let num = n;

  while (num % 2 === 0) {
    largest = 2;
    num /= 2;
  }

  for (let factor = 3; factor * factor <= num; factor += 2) {
    while (num % factor === 0) {
      largest = factor;
      num /= factor;
    }
  }

  if (num > 1) {
    largest = num;
  }

  return largest;
};
