const willItFly = (q, w) => {
  const sum = q.reduce((total, item) => total + item, 0);

  if (sum > w) {
    return false;
  }

  let i = 0;
  let j = q.length - 1;

  while (i < j) {
    if (q[i] !== q[j]) {
      return false;
    }
    i++;
    j--;
  }

  return true;
};
