const skjkasdkd = (lst) => {
  const isPrime = (n) => {
    if (n < 2) return false;
    if (n === 2) return true;
    if (n % 2 === 0) return false;

    for (let i = 3; i * i <= n; i += 2) {
      if (n % i === 0) return false;
    }

    return true;
  };

  let largestPrime = -Infinity;

  for (const n of lst) {
    if (isPrime(n) && n > largestPrime) {
      largestPrime = n;
    }
  }

  if (largestPrime === -Infinity) return 0;

  let sum = 0;
  while (largestPrime > 0) {
    sum += largestPrime % 10;
    largestPrime = Math.floor(largestPrime / 10);
  }

  return sum;
};
