const selectWords = (s, n) => {
  if (s === '') return [];

  const words = s.trim().split(/\s+/).filter(Boolean);
  const vowels = new Set(['a', 'e', 'i', 'o', 'u']);
  const result = [];

  for (const word of words) {
    let consonantCount = 0;

    for (const char of word) {
      if (!vowels.has(char.toLowerCase())) {
        consonantCount++;
      }
    }

    if (consonantCount === n) {
      result.push(word);
    }
  }

  return result;
};
