  const lo = Math.max(interval1[0], interval2[0]);
  const hi = Math.min(interval1[1], interval2[1]);

  if (hi < lo) return "NO";

  const len = hi - lo;

  if (len < 2) return "NO";

  for (let i = 2; i * i <= len; i++) {
    if (len % i === 0) return "NO";
