const minPath = (grid, k) => {
  const n = grid.length;
  let startRow = -1;
  let startCol = -1;

  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (grid[i][j] === 1) {
        startRow = i;
        startCol = j;
        break;
      }
    }
    if (startRow !== -1) break;
  }

  let minNeighbor = Infinity;
  const directions = [
    [-1, 0],
    [1, 0],
    [0, -1],
    [0, 1],
  ];

  for (const [dr, dc] of directions) {
    const nr = startRow + dr;
    const nc = startCol + dc;
    if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
      if (grid[nr][nc] < minNeighbor) {
        minNeighbor = grid[nr][nc];
      }
    }
  }

  const result = [];
  for (let i = 0; i < k; i++) {
    result.push(i % 2 === 0 ? 1 : minNeighbor);
  }

  return result;
};
