const doAlgebra = (operator, operand) => {
  const ops = operator.slice();
  const nums = operand.slice();

  const apply = (i) => {
    const op = ops[i];
    const a = nums[i];
    const b = nums[i + 1];
    let result;

    switch (op) {
      case '+':
        result = a + b;
        break;
      case '-':
        result = a - b;
        break;
      case '*':
        result = a * b;
        break;
      case '//':
        result = Math.floor(a / b);
        break;
      case '**':
        result = a ** b;
        break;
      default:
        throw new Error(`Unknown operator: ${op}`);
    }

    nums[i] = result;
    nums.splice(i + 1, 1);
    ops.splice(i, 1);
  };

  while (ops.includes('**')) {
    for (let i = ops.length - 1; i >= 0; i--) {
      if (ops[i] === '**') {
        apply(i);
        break;
      }
    }
  }

  while (ops.some(op => op === '*' || op === '//')) {
    for (let i = 0; i < ops.length; i++) {
      if (ops[i] === '*' || ops[i] === '//') {
        apply(i);
        break;
      }
    }
  }

  while (ops.length > 0) {
    apply(0);
  }

  return nums[0];
};
