const solve = (s) => {
  let hasLetter = false;
  let result = "";

  for (let i = 0; i < s.length; i++) {
    let code = s[i].charCodeAt();

    if (code >= 65 && code <= 90) {
      code += 32;
      hasLetter = true;
    } else if (code >= 97 && code <= 122) {
      code -= 32;
      hasLetter = true;
    }

    result += String.fromCharCode(code);
  }

  if (hasLetter) {
    return result;
  }

  let reversed = "";
  for (let i = result.length - 1; i >= 0; i--) {
    reversed += result[i];
  }

  return reversed;
};
